/** Windows 11 24H2 / Server 2025 networking subset. No Windows binary is executed. */
export const WINDOWS_PROFILE = {client:'Windows 11, version 24H2',server:'Windows Server 2025',scope:'NetworkSim networking subset'} as const;
export interface WindowsRemoteOptions {port?:number;addressFamily?:4|6}
export interface WindowsCLIOptions { remoteCommand?: (protocol:'ssh'|'telnet', args:string[],options?:WindowsRemoteOptions)=>string[] }
class WindowsError extends Error {}
function invalid(message='The syntax of the command is incorrect.'):never{throw new WindowsError(message);}
function unsupported(feature:string):never{return invalid(`${feature} is not implemented in the NetworkSim Windows networking subset.`);}
const exact=(args:string[],count:number)=>{if(args.length!==count)invalid();};
const number=(value:string|undefined,min:number,max:number)=>{if(value===undefined||!/^\d+$/.test(value)||Number(value)<min||Number(value)>max)invalid(`Value must be between ${min} and ${max}.`);return Number(value);};
