type ProbeOptions={target:string;label:string;count:number;bytes:number;ttl:number;timeout:number;df:boolean;continuous:boolean};
type Continuous={generation:number;options:ProbeOptions;sent:number;received:number;times:number[];result?:PingResult;emitted:number;timer?:TimerHandle};

