  private traceOptions(args:string[],path=false):{target:string;label:string;maxHops:number;timeout:number;queries:number;period:number;resolveNames:boolean}{let resolveNames=true,label:string|undefined,family:4|6|undefined,maxHops=30,timeout=path?3000:4000,queries=100,period=250;for(let i=0;i<args.length;i++){const token=args[i],flag=token.replace(/^\//,'-').toLowerCase();if(!/^[-/]/.test(token)){if(label)invalid();label=token;continue;}if(flag==='-4'||flag==='-6'){family=flag==='-4'?4:6;continue;}if(flag==='-d'||path&&flag==='-n'){resolveNames=false;continue;}if(flag==='-h'){maxHops=number(args[++i],1,64);continue;}if(flag==='-w'){timeout=number(args[++i],1,60000);continue;}if(path&&flag==='-q'){queries=number(args[++i],1,100);continue;}if(path&&flag==='-p'){period=number(args[++i],1,60000);continue;}invalid('Bad option '+token+'.');}if(!label)invalid();return {target:this.resolve(label,family),label,maxHops,timeout,queries,period,resolveNames};}
